func threeSum(_ nums: [Int]) -> [[Int]] {
    let a = nums.sorted()
    var result: [[Int]] = []
    for i in a.indices where a[i] <= 0 {
        if i > 0 && a[i] == a[i - 1] { continue }
        var l = i + 1, r = a.count - 1
        while l < r {
            let s = a[i] + a[l] + a[r]
            if s < 0 { l += 1 }
            else if s > 0 { r -= 1 }
            else {
                result.append([a[i], a[l], a[r]])
                l += 1; r -= 1
                while l < r && a[l] == a[l - 1] { l += 1 }
            }
        }
    }
    return result
}
